import type { MetadataRoute } from "next"

/**
 * docs.themys.ca is a fully public static export — there is no private surface
 * to keep out of the index, so the only job here is to point crawlers at the
 * sitemap generated by scripts/generate-sitemap.mjs.
 */
const DOCS_ORIGIN = "https://docs.themys.ca"

/**
 * Required by `output: "export"`: without it this metadata route fails the
 * build with "export const dynamic = 'force-static' ... not configured on
 * route /robots.txt with output: export".
 */
export const dynamic = "force-static"

export default function robots(): MetadataRoute.Robots {
  return {
    rules: {
      userAgent: "*",
      allow: "/",
    },
    sitemap: `${DOCS_ORIGIN}/sitemap.xml`,
  }
}
